function DivElementorWidgetContainer52() {
  return (
    <div className="[word-break:break-word] content-stretch flex flex-col font-['Poppins:Regular',sans-serif] gap-[24px] items-start leading-[0] not-italic relative shrink-0 text-[16px] text-black w-full whitespace-nowrap" data-name="div.elementor-widget-container">
      <div className="flex flex-col justify-center relative shrink-0">
        <p className="leading-[24px] mb-0">Ein Full-Stack-Entwickler ist ein Programmierer, der grundlegende Kenntnisse in allen Schichten einer</p>
        <p className="leading-[24px] mb-0">Anwendung hat. Jede Schicht wird als „Stack“ bezeichnet. Full-Stack-Webentwickler haben die Fähigkeit,</p>
        <p className="leading-[24px] mb-0">vollständige Webanwendungen und Websites zu entwerfen, die sowohl Frontend- als auch Backend-</p>
        <p className="leading-[24px] mb-0">Fähigkeiten erfordern. Sie arbeiten an der Datenbank und der Fehlersuche von Webanwendungen oder</p>
        <p className="leading-[24px]">Websites. Bist du bereit, deiner Karriere einen Schub zu geben?</p>
      </div>
      <div className="flex flex-col justify-center relative shrink-0">
        <p className="leading-[24px] mb-0">Das von uns angebotene Full Stack Entwicklung-Programm kann jedem Anfänger den Prozess</p>
        <p className="leading-[24px] mb-0">näherbringen oder Fachleute auf mittlerem bis fortgeschrittenem Niveau auf die nächste Stufe in ihrer</p>
        <p className="leading-[24px] mb-0">Karriere bringen! Der Lernpfad beginnt mit dem IT-Framework für Anfänger und setzt sich mit Kursmodulen</p>
        <p className="leading-[24px]">für Front-End- und Back-End-Entwickler fort.</p>
      </div>
      <div className="flex flex-col justify-center relative shrink-0">
        <p className="leading-[24px] mb-0">Ein Full Stack Developer ist ein Software- und Anwendungsentwickler, der gut gerüstet ist, um sowohl im</p>
        <p className="leading-[24px] mb-0">Front-End (Client-Seite) als auch im Back-End (Server-Seite) von Webanwendungen zu arbeiten. Du wirst</p>
        <p className="leading-[24px] mb-0">die aktuellsten Frontend- und Backend-Tools durch einen projektbasierten Lehrplan erlernen. Du wirst</p>
        <p className="leading-[24px]">Projekte erstellen, um dein Portfolio und deine GitHub-Konten zu füllen.</p>
      </div>
      <div className="flex flex-col justify-center relative shrink-0">
        <p className="leading-[24px] mb-0">Das Full Stack Entwicklung-Programm bietet dir Fachkenntnisse in einem oder beiden Zweigen deiner Wahl:</p>
        <p className="leading-[24px]">Developer Associate und Full Stack Developer.</p>
      </div>
    </div>
  );
}

